"""Gear_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 3 extrusion(s) and 3 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python Gear_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along z
z1 = 0.95    # level along z
z2 = 10.0    # level along z
z3 = 30.0    # level along z
z4 = 39.05    # level along z
z5 = 40.0    # level along z
hole_d = 184.9

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


def turn(p, centre, deg):
    """Point p turned by deg about the axis through centre along DIR."""
    from cadquery import Vertex
    q = Vertex.makeVertex(*p).rotate(Vector(*centre), Vector(*centre) + Vector(*DIR), deg)
    return q.toTuple()


# ---- 1. extrusion: z 0.95 to 39.05 ------------------------------
count_1 = 48                  # the outline repeats 48 times about the centre
centre_1 = P(105.8049, 105.7972)
v = [                            # vertices of one period
    P(211.63, 107.9685),
    P(211.3692, 111.9933),
    P(205.0108, 113.4527),
    P(201.842, 113.3417),
    P(201.377, 118.2592),
    P(206.8627, 119.7294),
]
v.append(turn(v[0], centre_1, 360.0 / count_1))   # the period ends where the next begins
period_1 = [
    cf.segment(v[0], v[1]),
    cf.segment(v[1], v[2]),
    cf.segment(v[2], v[3]),
    cf.segment(v[3], v[4]),
    cf.segment(v[4], v[5]),
    cf.segment(v[5], v[6]),
]
outline_1 = cf.wire(*[
    e.rotate(Vector(*centre_1), Vector(*centre_1) + Vector(*DIR), 360.0 * m / count_1)
    for m in range(count_1) for e in period_1
])
part = prism(outline_1, z1, z4)

# ---- round holes: (x, y, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (105.8, 105.8, hole_d, z1, z2),
    (105.8, 105.8, hole_d, z3, z4),
]:
    part = part - hole(a, b, d, lo, hi)

# ---- 2. extrusion: z 0.0 to 10.0 ------------------------------
outline_2 = cf.wire(
    Edge.makeCircle(25.0, P(105.8, 105.8), DIR),
)
part = part + prism(outline_2, z0, z2)

# ---- 3. extrusion: z 30.0 to 40.0 ------------------------------
outline_3 = cf.wire(
    Edge.makeCircle(25.0, P(105.8, 105.8), DIR),
)
part = part + prism(outline_3, z3, z5)

# ---- 4. cut: z 0.0 to 40.0 ------------------------------
outline_4 = cf.wire(
    cf.segment(P(100.8, 125.25), P(110.8, 125.25)),
    cf.segment(P(110.8, 125.25), P(110.8, 117.2564)),
    Edge.makeThreePointArc(P(110.8, 117.2564), P(105.8038, 93.3), P(100.8, 117.2564)),
    cf.segment(P(100.8, 117.2564), P(100.8, 125.25)),
)
part = part - prism(outline_4, z0, z5)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "Gear_exact.step")
